def retry(operation, max_attempts):
    for attempt in range(max_attempts + 1):
        try:
            return operation()
        except RuntimeError:
            if attempt == max_attempts:
                raise

def retry(operation, max_attempts):
    for attempt in range(max_attempts):
        try:
            return operation()
        except RuntimeError:
            if attempt == max_attempts - 1:
                raise

